{
  "version": 1,
  "defaultSuite": "smoke",
  "suites": {
    "smoke": [
      {
        "action": "assert",
        "expr": "document.body.innerText.includes('资讯已更新')",
        "matcher": "truthy"
      },
      {
        "action": "assert",
        "expr": "document.querySelectorAll('.news-press').length > 5",
        "matcher": "truthy"
      },
      {
        "action": "assert",
        "expr": "Number((document.body.innerText.match(/全部\\s*(\\d+)/) || [0, 0])[1]) > 20",
        "matcher": "truthy"
      },
      {
        "action": "assert",
        "expr": "/\\d+\\s*个来源/.test(document.body.innerText)",
        "matcher": "truthy"
      },
      {
        "action": "eval",
        "expr": "(() => { const b = [...document.querySelectorAll('button')].find(x => x.textContent.replace(/\\s+/g, ' ').trim().startsWith('科技')); if (!b) throw new Error('topic chip 科技 not found'); b.click(); return b.textContent.replace(/\\s+/g, ' ').trim() })()"
      },
      { "action": "wait", "ms": 1200 },
      {
        "action": "assert",
        "expr": "document.querySelectorAll('.news-press').length > 3",
        "matcher": "truthy"
      },
      {
        "action": "eval",
        "expr": "(() => { const b = [...document.querySelectorAll('button')].find(x => x.textContent.trim() === '订阅'); if (!b) throw new Error('订阅 tab not found'); b.click(); return 'ok' })()"
      },
      { "action": "wait", "ms": 2200 },
      {
        "action": "assert",
        "expr": "document.body.innerText.includes('添加订阅源')",
        "matcher": "truthy"
      },
      {
        "action": "assert",
        "expr": "(document.body.innerText.match(/rss\\s*·/g) || []).length >= 5",
        "matcher": "truthy"
      },
      {
        "action": "assert",
        "expr": "['Google 头条', 'BBC 中文网', 'IT之家'].every(n => document.body.innerText.includes(n))",
        "matcher": "truthy"
      },
      {
        "action": "eval",
        "expr": "(() => { const b = [...document.querySelectorAll('button')].find(x => x.textContent.trim() === '资讯'); if (!b) throw new Error('资讯 tab not found'); b.click(); return 'ok' })()"
      },
      { "action": "wait", "ms": 900 },
      {
        "action": "assert",
        "expr": "document.querySelectorAll('.news-press').length > 3",
        "matcher": "truthy"
      },
      { "action": "assert", "matcher": "noHorizontalOverflow" }
    ],
    "offline": [
      {
        "action": "assert",
        "expr": "!!document.querySelector('#root') && document.querySelector('#root').children.length > 0",
        "matcher": "truthy"
      },
      {
        "action": "assert",
        "expr": "['资讯', '订阅', '收藏'].every(t => [...document.querySelectorAll('button')].some(b => b.textContent.trim() === t))",
        "matcher": "truthy"
      },
      {
        "action": "assert",
        "expr": "!/undefined|NaN|\\[object Object\\]/.test(document.body.innerText)",
        "matcher": "truthy"
      }
    ]
  }
}

// 资讯（com.aibox.news）—— NewsPluginKit 的 React 复刻。
//
// 根职责：装配 store / aggregator / broadcast → 接宿主外壳（tabs / toolbar / menu / browser / tts / ai）
// → 路由子页 → 渲染当前 Tab。宿主能力缺席时全部走自绘降级件（见 components/Shell.jsx）。

import React from 'react'
import { THEME_CSS, C } from './components/theme.js'
import { NavBar, SearchField, TabBar, ToolbarButton } from './components/Shell.jsx'
import FeedPage from './components/FeedPage.jsx'
import SourcesPage from './components/SourcesPage.jsx'
import SavedPage from './components/SavedPage.jsx'
import SettingsPage from './components/SettingsPage.jsx'
import AddSourcePage from './components/AddSourcePage.jsx'
import DiagnosticsPage from './components/DiagnosticsPage.jsx'
import ClusterDetail from './components/ClusterDetail.jsx'
import BroadcastBar, { BroadcastNotice } from './components/BroadcastBar.jsx'
import AIPanel from './components/AIPanel.jsx'
import { fetchSingleSource } from './lib/aggregator.js'
import { getSession, whenReady } from './lib/session.js'
import { registerActions } from './lib/actions.js'
import { useSubpageStack } from './lib/subpages.js'
import { openArticle as performOpen, knowledgeMarkdown } from './lib/reading.js'
import {
  capabilities, browserAvailability, aiAvailability, findTool, callTool, onEvent, onNamespaceEvent,
} from './lib/host.js'
import { currentLocale, makeT, onLocaleChanged } from './i18n/index.js'

// 对外提供的 4 个 AI 工具（news_search / read / source / save）+ ⋯ 菜单的朗读动作。
// **模块求值期就注册**：无头执行时页面不挂载任何组件，等 React 副作用就来不及了。
registerActions()

const TABS = [
  { id: 'feed', titleKey: 'news.tab.feed', icon: 'newspaper', selectedIcon: 'newspaper.fill' },
  { id: 'subs', titleKey: 'news.tab.subs', icon: 'dot.radiowaves.up.forward' },
  { id: 'saved', titleKey: 'news.tab.saved', icon: 'bookmark', selectedIcon: 'bookmark.fill' },
]

function useForceRender() {
  const [, setTick] = React.useState(0)
  return React.useCallback(() => setTick((n) => n + 1), [])
}

/** 主题：CSS 变量注入 + 把有效颜色方案同步给 antd-mobile 的暗色开关。 */
function useThemeSetup() {
  React.useEffect(() => {
    if (document.getElementById('__news_css__')) return
    const style = document.createElement('style')
    style.id = '__news_css__'
    style.textContent = THEME_CSS
    document.head.appendChild(style)
  }, [])
  React.useEffect(() => {
    const query = window.matchMedia ? window.matchMedia('(prefers-color-scheme: dark)') : null
    const apply = () => {
      const dark = query ? query.matches : false
      document.documentElement.setAttribute('data-prefers-color-scheme', dark ? 'dark' : 'light')
    }
    apply()
    if (query && query.addEventListener) {
      query.addEventListener('change', apply)
      return () => query.removeEventListener('change', apply)
    }
    return undefined
  }, [])
}

export default function App() {
  useThemeSetup()
  const rerender = useForceRender()

  const [locale, setLocale] = React.useState(currentLocale)
  const t = React.useMemo(() => makeT(locale), [locale])
  // 子页标题在 push 那一刻要用最新的翻译函数，而 push 回调是稳定的 —— 经 ref 取值。
  const tRef = React.useRef(t)
  tRef.current = t

  // 与 AI 工具共用同一份状态（lib/session.js 的模块级单例），UI 只是它的一个消费方。
  const session = getSession()
  const { store, agg, broadcast } = session

  const [ready, setReady] = React.useState(false)
  const [tab, setTab] = React.useState('feed')
  const [query, setQuery] = React.useState('')
  // 子页栈 = 宿主原生页栈的镜像（见 lib/subpages.js）：进子页走 `aibox.navigation.push`，
  // 返回一律经 popstate 回来，于是最左缘左滑是**系统自己的** interactive pop。
  const subpages = useSubpageStack({
    pathFor: routePath,
    titleFor: (row) => routeTitle(row, tRef.current),
  })
  const { stack } = subpages
  const [aiSession, setAISession] = React.useState(null)
  const [now, setNow] = React.useState(() => Date.now())
  const [shell, setShell] = React.useState({ tabsRendered: false, toolbarRendered: false, searchRendered: false })
  const [caps, setCaps] = React.useState({ hasAI: false, hasTTS: false, hasKB: false, browserModes: [] })

  // —— 订阅三个模型的变化 ——
  React.useEffect(() => {
    const offs = [store.subscribe(rerender), agg.subscribe(rerender), broadcast.subscribe(rerender)]
    return () => offs.forEach((off) => off())
  }, [store, agg, broadcast, rerender])

  // —— 语言：跟随宿主有效 UI 语言，切换时重渲染而不重载 ——
  React.useEffect(() => onLocaleChanged(setLocale), [])

  // —— 相对时间每分钟走一步 ——
  React.useEffect(() => {
    const timer = window.setInterval(() => setNow(Date.now()), 60000)
    return () => window.clearInterval(timer)
  }, [])

  // —— 启动：hydrate 快照秒显 → 按 TTL 静默刷新（stale-while-revalidate）——
  React.useEffect(() => {
    let cancelled = false
    const boot = async () => {
      await whenReady()
      if (cancelled) return
      setReady(true)
      if (store.settings.autoRefresh) agg.refresh({ force: false })
    }
    boot()
    return () => { cancelled = true }
  }, [store, agg])

  // —— 能力探测：拿不到就整块不渲染入口，不留「点了没反应」的按钮 ——
  React.useEffect(() => {
    let cancelled = false
    const probe = async () => {
      const [ai, browser, kb] = await Promise.all([
        capabilities.ai ? aiAvailability() : Promise.resolve({ available: false }),
        browserAvailability(),
        capabilities.tools ? findTool('vault_create') : Promise.resolve(false),
      ])
      if (cancelled) return
      setCaps({
        hasAI: !!ai.available,
        hasTTS: capabilities.tts,
        hasKB: !!kb,
        browserModes: browser.modes,
      })
    }
    probe()
    return () => { cancelled = true }
  }, [])

  const openAI = React.useCallback((article) => {
    // 没有 AI 权限时整个 ✨ 入口不渲染；这里再兜一层，防宿主事件把面板顶出来。
    if (!caps.hasAI) return
    setAISession(article
      ? { identity: `news:${article.id}`, seed: t('news.ai.analyze', article.title, article.url) }
      : { identity: 'news', seed: null })
  }, [caps.hasAI, t])

  const toggleBroadcast = React.useCallback(() => {
    if (broadcast.active) broadcast.stop({ userInitiated: true })
    else broadcast.start(session.visibleArticles)
  }, [broadcast, session])

  // —— 宿主外壳接线 ——
  const openAIRef = React.useRef(openAI)
  openAIRef.current = openAI
  // 外壳接线只跑一次，而 reset 要在每次切 Tab 时清掉子页栈 —— 经 ref 取最新那一个。
  const resetRef = React.useRef(subpages.reset)
  resetRef.current = subpages.reset

  React.useEffect(() => {
    let cancelled = false
    const offs = []
    const wire = async () => {
      const api = window.aibox
      if (api && api.tabs && typeof api.tabs.getState === 'function') {
        try {
          const state = await api.tabs.getState()
          if (!cancelled && state && state.rendered) {
            setShell((current) => ({ ...current, tabsRendered: true }))
            if (state.selected) setTab(state.selected)
          }
        } catch (error) { /* 宿主没这能力：留给自绘 TabBar */ }
        offs.push(onNamespaceEvent('tabs', 'changed', (state) => {
          if (!state) return
          // `rendered` 会**在挂载之后翻转**（形态切换、控制器重建都会重发 changed）。
          // 只在启动那一刻判断一次，自绘 TabBar 就会永远缺席或永远多一条。
          const rendered = state.rendered !== false
          setShell((current) => (current.tabsRendered === rendered
            ? current : { ...current, tabsRendered: rendered }))
          if (state.selected) { setTab(state.selected); resetRef.current() }
        }))
      }
      if (api && api.toolbar && typeof api.toolbar.getState === 'function') {
        try {
          const state = await api.toolbar.getState()
          if (!cancelled && state) {
            setShell((current) => ({
              ...current,
              toolbarRendered: state.rendered !== false,
              searchRendered: !!(state.search && state.search.rendered),
            }))
          }
        } catch (error) { /* 同上 */ }
        offs.push(onNamespaceEvent('toolbar', 'invoke', (payload) => {
          if (payload && payload.id === 'ai') openAIRef.current(null)
        }))
        offs.push(onNamespaceEvent('toolbar', 'searchChanged', (payload) => {
          setQuery(String((payload && payload.query) || ''))
        }))
      }
      // ⋯ 菜单里的「朗读 / 停止朗读」经 manifest.actions + scene.menu 落到 lib/actions.js 的
      // `toggleBroadcast`（已在模块求值期注册），这里不再重复注册。
      offs.push(onEvent('lifecycle.background', () => { agg.persistNow() }))
    }
    wire()
    return () => { cancelled = true; offs.forEach((off) => off && off()) }
  }, [agg])

  // —— 顶栏标题与四态右上角 ——
  const showBroadcast = tab === 'feed' && caps.hasTTS && agg.timeline.length > 0
  React.useEffect(() => {
    const api = window.aibox
    const current = TABS.find((row) => row.id === tab) || TABS[0]
    const title = stack.length > 0 ? routeTitle(stack[stack.length - 1], t) : t(current.titleKey)
    document.title = title
    if (api && api.navigation && typeof api.navigation.setTitle === 'function') api.navigation.setTitle(title)
    if (api && api.toolbar && typeof api.toolbar.update === 'function') {
      // 只改 ✨。`more` 是 `role:hostMenu` 的位置标记、不是自己的按钮，而宿主 ⋯ 菜单是保留出口、
      // 声不声明都在（platform 合同 §2.1）——所以"没有可播报内容时右上角只剩 ✨"这一态改由
      // **隐藏菜单项本身**表达（见下面的 menu.update），而不是去藏宿主菜单。
      api.toolbar.update({ items: { ai: { hidden: !caps.hasAI } } }).catch(() => {})
    }
    if (api && api.menu && typeof api.menu.update === 'function') {
      api.menu.update({
        items: {
          listen: {
            hidden: !showBroadcast,
            title: t(broadcast.active ? 'news.action.stopListening' : 'news.action.listen'),
          },
        },
      }).catch(() => {})
    }
  }, [tab, stack, caps.hasAI, showBroadcast, broadcast.active, t])

  const readKeys = React.useMemo(() => store.readKeys, [store, store.version]) // eslint-disable-line react-hooks/exhaustive-deps
  const savedKeys = React.useMemo(() => store.savedKeys, [store, store.version]) // eslint-disable-line react-hooks/exhaustive-deps

  const { push: navigate, back } = subpages

  const ctx = React.useMemo(() => ({
    t,
    locale,
    now,
    store,
    agg,
    broadcast,
    settings: store.settings,
    storeVersion: store.version,
    readVersion: store.version,
    readKeys,
    savedKeys,
    query,
    searchRendered: shell.searchRendered,
    hasAI: caps.hasAI,
    hasTTS: caps.hasTTS,
    hasKnowledgeCapture: caps.hasKB,
    speakingId: broadcast.active && broadcast.current ? broadcast.current.id : null,
    actions: {
      navigate,
      back,
      refresh: (force) => agg.refresh({ force }),
      setVisibleArticles: (list) => { session.visibleArticles = list },
      fetchSource: async (feed) => {
        const result = await fetchSingleSource(feed, store.settings)
        return result.articles
      },
      // 打开失败（宿主没装浏览器 / 浏览器能力未被授权 / 降级链全不可用）必须**说出来**：
      // 原来只是把返回值丢掉，用户看到的就是「点了没反应」。
      openArticle: async (article) => {
        const opened = await performOpen(article, { store, settings: store.settings })
        if (!opened) broadcast.showNotice('news.x.openFailed')
        return opened
      },
      openCluster: (item) => navigate({ name: 'cluster', title: item.lead.title, articles: [item.lead, ...item.related] }),
      toggleSaved: (article) => (store.savedKeys.has(article.id) ? store.unsave(article.id) : store.save(article)),
      unsave: (id) => store.unsave(id),
      toggleRead: (article) => (store.readKeys.has(article.id) ? store.markUnread(article.id) : store.markRead(article)),
      removeHistory: (key) => store.removeHistory(key),
      analyze: (article) => openAI(article),
      askAI: (seed) => setAISession({ identity: 'news', seed }),
      listenFrom: (article, sequence) => broadcast.startFrom(article, sequence),
      saveToKnowledgeBase: async (article) => {
        const result = await callTool('vault_create', {
          name: String(article.title || 'news').slice(0, 80),
          content: knowledgeMarkdown(article),
        })
        // 已知运行时缺口：Toast.show 渲染为空 → 反馈统一走自绘提示条。
        broadcast.showNotice(result && result.ok !== false ? 'news.x.savedToKB' : 'news.x.saveKBFailed')
      },
      updateSettings: (patch) => store.updateSettings(patch),
      clearContentCache: () => store.clearContentCache(),
      addFeed: (input) => store.addFeed(input),
      removeFeed: (id) => store.removeFeed(id),
      setFeedEnabled: (id, enabled) => store.setFeedEnabled(id, enabled),
      moveFeed: (id, direction) => store.moveFeed(id, direction),
    },
  }), [t, locale, now, store, agg, broadcast, store.version, agg.timelineRevision, query,
    shell.searchRendered, caps.hasAI, caps.hasTTS, caps.hasKB, readKeys, savedKeys,
    navigate, back, openAI, broadcast.active, broadcast.index]) // eslint-disable-line react-hooks/exhaustive-deps

  const { route } = subpages
  const currentTab = TABS.find((row) => row.id === tab) || TABS[0]

  const selectTab = (next) => {
    setTab(next)
    subpages.reset()
    const api = window.aibox
    if (api && api.tabs && typeof api.tabs.select === 'function') api.tabs.select(next).catch(() => {})
  }

  return (
    <div className="news-root">
      {/* 宿主画了顶栏就**不再自绘** —— 子页也不自绘：宿主在 `webDepth > 0` 时自己就有返回键，
          两条一起画等于两层导航栏、两个标题。没有宿主顶栏时（fullscreen 形态 / 无宿主）才补上。 */}
      {!shell.toolbarRendered ? (
        <NavBar
          title={route ? routeTitle(route, t) : t(currentTab.titleKey)}
          onBack={route ? back : undefined}
          backLabel={t('news.x.back')}
          trailing={!route && !shell.toolbarRendered ? (
            <>
              {caps.hasAI ? (
                <ToolbarButton icon="sparkles" label={t('news.companion.title')} onClick={() => openAI(null)} />
              ) : null}
              {showBroadcast ? (
                <ToolbarButton
                  icon={broadcast.active ? 'stop.circle.fill' : 'speaker.wave.2'}
                  label={t(broadcast.active ? 'news.action.stopListening' : 'news.action.listen')}
                  onClick={toggleBroadcast}
                />
              ) : null}
            </>
          ) : null}
        />
      ) : null}

      {!route && !shell.searchRendered && tab === 'feed' ? (
        <SearchField value={query} onChange={setQuery} placeholder={t('news.search.prompt')} />
      ) : null}

      {!ready ? <div className="news-scroll" /> : (route ? renderRoute(route, ctx) : (
        <>
          {tab === 'feed' ? <FeedPage ctx={ctx} /> : null}
          {tab === 'subs' ? <SourcesPage ctx={ctx} /> : null}
          {tab === 'saved' ? <SavedPage ctx={ctx} /> : null}
        </>
      ))}

      <BroadcastNotice messageKey={broadcast.noticeKey} t={t} onDismiss={() => broadcast.dismissNotice()} />
      <BroadcastBar
        broadcast={broadcast}
        t={t}
        onOpenCurrent={() => { if (broadcast.current) ctx.actions.openArticle(broadcast.current) }}
      />

      {!shell.tabsRendered ? (
        <TabBar
          items={TABS.map((row) => ({ ...row, title: t(row.titleKey) }))}
          selected={tab}
          onSelect={selectTab}
        />
      ) : (
        <div style={{ height: 'env(safe-area-inset-bottom)', background: C.bg, flex: '0 0 auto' }} />
      )}

      <AIPanel ctx={ctx} session={aiSession} onClose={() => setAISession(null)} />
    </div>
  )
}

/** 子页在 history 里的路径。页面自己不读它，只为宿主诊断与 `navigation.getState().url` 可读。 */
function routePath(route) {
  if (!route) return '#/'
  if (route.name === 'source') return `#/source/${encodeURIComponent((route.feed && route.feed.id) || '')}`
  return `#/${route.name}`
}

function routeTitle(route, t) {
  if (!route) return ''
  switch (route.name) {
    case 'settings': return t('news.settings.title')
    case 'addSource': return t('news.add.nav')
    case 'diagnostics': return t('news.diagnostics.title')
    case 'cluster': return t('news.cluster.title')
    case 'source': return route.feed.title
    default: return ''
  }
}

function renderRoute(route, ctx) {
  switch (route.name) {
    case 'settings': return <SettingsPage ctx={ctx} />
    case 'addSource': return <AddSourcePage ctx={ctx} />
    case 'diagnostics': return <DiagnosticsPage ctx={ctx} />
    case 'cluster': return <ClusterDetail ctx={ctx} cluster={route} />
    case 'source': return <FeedPage ctx={ctx} sourceFeed={route.feed} />
    default: return null
  }
}

// 添加订阅源表单：名称（可空 → 用 endpoint 顶替）、地址、类型 Picker（rawValue 不本地化）、主题 Picker。
// 「测试来源」走正式抓取链路但不写库；改 endpoint / kind / topic 会清空测试结果。
// 添加逻辑：endpoint 以 `/` 开头强制视为 rsshub；sortOrder = max+1；enabled = true。

import React from 'react'
import Icon from './Icon.jsx'
import PickerRow from './OptionPicker.jsx'
import { Card, SectionFooter, Spinner } from './primitives.jsx'
import { C, SPACE } from './theme.js'
import { FEED_KINDS, TOPIC_ORDER, topicKey } from '../lib/catalog.js'

function Field({ label, children }) {
  return (
    <div style={{
      display: 'flex', alignItems: 'center', gap: SPACE.s3,
      padding: `11px ${SPACE.s4}px`, borderBottom: `0.5px solid ${C.line}`,
    }}
    >
      <span style={{ fontSize: 15, color: C.ink, width: 68, flex: '0 0 auto' }}>{label}</span>
      {children}
    </div>
  )
}

const inputStyle = {
  flex: '1 1 auto', minWidth: 0, border: 0, outline: 'none', background: 'transparent',
  font: 'inherit', fontSize: 15, color: 'var(--news-ink)', textAlign: 'right',
}

export default function AddSourcePage({ ctx }) {
  const [title, setTitle] = React.useState('')
  const [endpoint, setEndpoint] = React.useState('')
  const [kind, setKind] = React.useState('rss')
  const [topic, setTopic] = React.useState('top')
  const [testing, setTesting] = React.useState(false)
  const [result, setResult] = React.useState(null)

  const clearResult = () => setResult(null)

  const runTest = async () => {
    setTesting(true)
    setResult(null)
    const effectiveKind = endpoint.trim().startsWith('/') ? 'rsshub' : kind
    const outcome = await ctx.actions.fetchSource({
      id: 'test',
      title: title.trim() || endpoint.trim(),
      endpoint: endpoint.trim(),
      kind: effectiveKind,
      topic,
    })
    setTesting(false)
    setResult(outcome.length > 0 ? { ok: true, count: outcome.length } : { ok: false })
  }

  const canSubmit = endpoint.trim().length > 0

  return (
    <div className="news-scroll">
      <div style={{ height: SPACE.s3 }} />
      <Card>
        <Field label={ctx.t('news.add.title')}>
          <input value={title} onChange={(event) => setTitle(event.target.value)} style={inputStyle} />
        </Field>
        <Field label="">
          <input
            value={endpoint}
            onChange={(event) => { setEndpoint(event.target.value); clearResult() }}
            placeholder={ctx.t('news.add.endpoint')}
            autoCapitalize="none"
            autoCorrect="off"
            spellCheck={false}
            inputMode="url"
            style={{ ...inputStyle, textAlign: 'left' }}
          />
        </Field>
        {/* 类型的选项直接用 rawValue，与原生一致（不本地化）。 */}
        <PickerRow
          title={ctx.t('news.add.kind')}
          value={kind}
          options={FEED_KINDS.map((value) => ({ value, label: value }))}
          onChange={(value) => { setKind(value); clearResult() }}
          cancelLabel={ctx.t('news.action.cancel')}
        />
        <PickerRow
          title={ctx.t('news.add.topic')}
          value={topic}
          options={TOPIC_ORDER.map((value) => ({ value, label: ctx.t(topicKey(value)) }))}
          onChange={(value) => { setTopic(value); clearResult() }}
          cancelLabel={ctx.t('news.action.cancel')}
          last
        />
      </Card>

      <div style={{ height: SPACE.s5 }} />
      <Card>
        <button
          type="button"
          className="news-btn news-press"
          disabled={!canSubmit || testing}
          onClick={runTest}
          style={{
            display: 'flex', alignItems: 'center', gap: SPACE.s2, width: '100%',
            padding: `12px ${SPACE.s4}px`, fontSize: 15,
            color: canSubmit ? C.brand : C.muted,
            borderBottom: `0.5px solid ${C.line}`,
          }}
        >
          {testing ? <Spinner size={15} color={C.brand} /> : <Icon name="waveform.path.ecg" size={16} />}
          {ctx.t('news.add.test')}
        </button>
        {result ? (
          <div style={{
            display: 'flex', alignItems: 'center', gap: SPACE.s2,
            padding: `12px ${SPACE.s4}px`, fontSize: 13,
            color: result.ok ? C.brand : C.orange,
            borderBottom: `0.5px solid ${C.line}`,
          }}
          >
            <Icon name={result.ok ? 'checkmark.circle.fill' : 'xmark.circle.fill'} size={16} />
            <span>{result.ok ? ctx.t('news.add.testSuccess', result.count) : ctx.t('news.add.testFailed')}</span>
          </div>
        ) : null}
        <button
          type="button"
          className="news-btn news-press"
          disabled={!canSubmit}
          onClick={async () => {
            await ctx.actions.addFeed({ title, endpoint, kind, topic })
            ctx.actions.back()
          }}
          style={{
            display: 'block', width: '100%', padding: `12px ${SPACE.s4}px`, fontSize: 15,
            color: canSubmit ? C.brand : C.muted, textAlign: 'center', fontWeight: 600,
          }}
        >
          {ctx.t('news.action.add')}
        </button>
      </Card>
      <SectionFooter>{ctx.t('news.add.testFooter')}</SectionFooter>
      <div style={{ height: 32 }} />
    </div>
  )
}

// ✨ 新闻助手 —— **近似实现**（README 有记）。
//
// 原生把这个入口交给宿主的「停靠式会话」：真聊天页、真工具（news_search / news_read）、按 identity
// （首页 "news" / 逐篇 "news:<id>"）持久续聊。小应用侧没有停靠会话 API，只有 `aibox.ai.generate`，
// 因此这里自绘一个轻量对话面板：同样的会话身份分档、同样的系统上下文与三个快捷 chip，
// 但**工具调用换成把当前时间线摘要塞进上下文**，且会话只存在于本次运行（不持久）。

import React from 'react'
import Icon from './Icon.jsx'
import { Sheet, Spinner } from './primitives.jsx'
import { C, SPACE } from './theme.js'
import { aiGenerate } from '../lib/host.js'

const QUICK_ACTIONS = [
  { key: 'today', icon: 'newspaper', labelKey: 'news.companion.today', seedKey: 'news.companion.today.p' },
  { key: 'bytopic', icon: 'square.grid.2x2', labelKey: 'news.companion.bytopic', seedKey: 'news.companion.bytopic.p' },
  { key: 'explain', icon: 'questionmark.circle', labelKey: 'news.companion.explain', seedKey: 'news.companion.explain.p' },
]

/** 时间线摘要：替代原生的 news_search 工具调用，让模型有据可依。 */
function timelineDigest(articles, limit = 40) {
  return articles.slice(0, limit)
    .map((article, i) => `${i + 1}. [${article.topic}] ${article.title} — ${article.sourceName}`)
    .join('\n')
}

export default function AIPanel({ ctx, session, onClose }) {
  const [turns, setTurns] = React.useState([])
  const [draft, setDraft] = React.useState('')
  const [busy, setBusy] = React.useState(false)
  const scroller = React.useRef(null)
  const seeded = React.useRef(false)

  const send = React.useCallback(async (text) => {
    const prompt = String(text || '').trim()
    if (!prompt || busy) return
    setDraft('')
    setTurns((rows) => [...rows, { role: 'user', text: prompt }])
    setBusy(true)
    const system = [
      ctx.t('news.companion.context'),
      ctx.t('news.ai.replyLang'),
      `Current timeline (most recent first):\n${timelineDigest(ctx.agg.timeline)}`,
    ].join('\n\n')
    try {
      const reply = await aiGenerate({ system, prompt, intent: 'balanced', maxTokens: 1200 })
      setTurns((rows) => [...rows, { role: 'assistant', text: String(reply || '') }])
    } catch (error) {
      const message = String((error && error.message) || error)
      setTurns((rows) => [...rows, { role: 'assistant', text: message.startsWith('aibox/') ? message : ctx.t('news.x.aiUnavailable') }])
    } finally {
      setBusy(false)
    }
  }, [busy, ctx])

  React.useEffect(() => {
    if (!session || seeded.current) return
    seeded.current = true
    if (session.seed) send(session.seed)
  }, [session, send])

  React.useEffect(() => {
    if (scroller.current) scroller.current.scrollTop = scroller.current.scrollHeight
  }, [turns, busy])

  return (
    <Sheet visible={!!session} onClose={onClose}>
      <div style={{ display: 'flex', flexDirection: 'column', height: '78dvh' }}>
        <div style={{
          display: 'flex', alignItems: 'center', gap: SPACE.s2,
          padding: `${SPACE.s3}px ${SPACE.s4}px`, borderBottom: `0.5px solid ${C.line}`,
        }}
        >
          <Icon name="sparkles" size={16} color={C.brand} />
          <span style={{ flex: '1 1 auto', fontSize: 16, fontWeight: 500, color: C.ink }}>
            {ctx.t('news.companion.title')}
          </span>
          <button
            type="button"
            className="news-btn news-press"
            onClick={onClose}
            aria-label={ctx.t('news.x.close')}
            style={{ color: C.muted, padding: 6 }}
          >
            <Icon name="xmark" size={15} />
          </button>
        </div>

        <div ref={scroller} style={{ flex: '1 1 auto', overflowY: 'auto', padding: SPACE.s4, display: 'flex', flexDirection: 'column', gap: SPACE.s3 }}>
          {turns.length === 0 && !busy ? (
            <span style={{ fontSize: 13, color: C.muted }}>{ctx.t('news.companion.context')}</span>
          ) : null}
          {turns.map((turn, i) => (
            <div
              key={i}
              style={{
                alignSelf: turn.role === 'user' ? 'flex-end' : 'flex-start',
                maxWidth: '86%',
                padding: `9px ${SPACE.s3}px`,
                borderRadius: 14,
                background: turn.role === 'user' ? C.brand : C.bg,
                color: turn.role === 'user' ? C.onBrand : C.ink,
                fontSize: 15,
                lineHeight: 1.45,
                whiteSpace: 'pre-wrap',
                wordBreak: 'break-word',
              }}
            >
              {turn.text}
            </div>
          ))}
          {busy ? (
            <div style={{ display: 'flex', alignItems: 'center', gap: 6, color: C.muted, fontSize: 13 }}>
              <Spinner size={14} color={C.brand} />
              {ctx.t('news.x.aiThinking')}
            </div>
          ) : null}
        </div>

        <div className="news-chips" style={{ display: 'flex', gap: 8, overflowX: 'auto', padding: `0 ${SPACE.s4}px ${SPACE.s2}px` }}>
          {QUICK_ACTIONS.map((action) => (
            <button
              key={action.key}
              type="button"
              className="news-btn news-press"
              onClick={() => send(ctx.t(action.seedKey))}
              style={{
                display: 'inline-flex', alignItems: 'center', gap: 5, flex: '0 0 auto',
                padding: '6px 11px', borderRadius: 999, fontSize: 13, color: C.ink,
                background: 'color-mix(in srgb, var(--news-line) 50%, transparent)',
              }}
            >
              <Icon name={action.icon} size={13} color={C.brand} />
              {ctx.t(action.labelKey)}
            </button>
          ))}
        </div>

        <div style={{
          display: 'flex', alignItems: 'center', gap: SPACE.s2,
          padding: `${SPACE.s2}px ${SPACE.s4}px`, borderTop: `0.5px solid ${C.line}`,
        }}
        >
          <input
            value={draft}
            onChange={(event) => setDraft(event.target.value)}
            onKeyDown={(event) => { if (event.key === 'Enter') send(draft) }}
            placeholder={ctx.t('news.x.askPlaceholder')}
            style={{
              flex: '1 1 auto', minWidth: 0, border: 0, outline: 'none', background: 'transparent',
              font: 'inherit', fontSize: 15, color: C.ink, padding: '8px 0',
            }}
          />
          <button
            type="button"
            className="news-btn news-press"
            onClick={() => send(draft)}
            disabled={busy || !draft.trim()}
            style={{ color: draft.trim() && !busy ? C.brand : C.muted, fontSize: 15, padding: 6 }}
          >
            {ctx.t('news.x.send')}
          </button>
        </div>
      </div>
    </Sheet>
  )
}

// 文章列表 + 长按菜单 + 可选左滑删除。资讯页 / 事件簇详情 / 订阅源下钻 / 收藏页共用。
// 长按菜单的**项与顺序**按 spec §2.5 / §4：条件不满足则整项不出现。

import React from 'react'
import ArticleRow from './ArticleRow.jsx'
import { ActionSheet, SwipeRow, useLongPress, useIncremental } from './primitives.jsx'
import { C, SPACE } from './theme.js'

function Item({ article, item, ctx, menuFor, swipe, sequence }) {
  const [menu, setMenu] = React.useState(false)
  const actions = menu ? menuFor(article, item, sequence) : []
  const press = useLongPress(() => setMenu(true), () => ctx.actions.openArticle(article))

  const body = (
    <div
      className="news-press"
      style={{ padding: `0 ${SPACE.s4}px`, background: C.surface }}
      {...press}
    >
      <ArticleRow
        article={article}
        isRead={ctx.readKeys.has(article.id)}
        relatedCount={item ? item.related.length : 0}
        isSaved={ctx.savedKeys.has(article.id)}
        isSpeaking={ctx.speakingId === article.id}
        locale={ctx.locale}
        t={ctx.t}
        now={ctx.now}
      />
      <div style={{ height: 0, borderBottom: `0.5px solid ${C.line}` }} />
    </div>
  )

  return (
    <>
      {swipe ? (
        <SwipeRow actionLabel={swipe.label} onAction={() => swipe.onAction(article)}>{body}</SwipeRow>
      ) : body}
      <ActionSheet
        visible={menu}
        title={article.title}
        actions={actions}
        cancelLabel={ctx.t('news.action.cancel')}
        onClose={() => setMenu(false)}
      />
    </>
  )
}

/**
 * @param items    时间线条目 `{ id, lead, related }`；或直接给 articles
 * @param menuFor  (article, item, sequence) => ActionSheet actions
 * @param swipe    `{ label, onAction }`，不给则无左滑
 */
export default function ArticleList({ items, ctx, menuFor, swipe, header, footer }) {
  const { visible, sentinel, hasMore } = useIncremental(items, 30)
  return (
    <div>
      {header}
      {visible.map((entry) => (
        <Item
          key={entry.id}
          article={entry.lead}
          item={entry}
          ctx={ctx}
          menuFor={menuFor}
          swipe={swipe}
          sequence={items}
        />
      ))}
      <div ref={sentinel} style={{ height: hasMore ? 24 : 0 }} />
      {footer}
    </div>
  )
}

/** 时间线 / 订阅源下钻 / 事件簇详情的长按菜单构造器。 */
export function buildArticleMenu(ctx, { includeRelated = true, includeCluster = true } = {}) {
  return (article, item, sequence) => {
    const actions = []
    if (includeRelated && includeCluster && item && item.related.length > 0) {
      actions.push({
        key: 'related',
        icon: 'rectangle.stack',
        label: ctx.t('news.action.relatedReports'),
        onSelect: () => ctx.actions.openCluster(item),
      })
    }
    if (ctx.hasAI) {
      actions.push({
        key: 'analyze',
        icon: 'sparkles',
        label: ctx.t('news.action.analyze'),
        onSelect: () => ctx.actions.analyze(article),
      })
    }
    if (ctx.hasTTS) {
      actions.push({
        key: 'listen',
        icon: 'speaker.wave.2',
        label: ctx.t('news.action.listen'),
        onSelect: () => ctx.actions.listenFrom(article, (sequence || []).map((row) => row.lead)),
      })
    }
    const saved = ctx.savedKeys.has(article.id)
    actions.push({
      key: 'save',
      icon: saved ? 'bookmark.slash' : 'bookmark',
      label: ctx.t(saved ? 'news.action.unsave' : 'news.action.save'),
      onSelect: () => ctx.actions.toggleSaved(article),
    })
    const read = ctx.readKeys.has(article.id)
    actions.push({
      key: 'read',
      icon: read ? 'circle' : 'checkmark.circle',
      label: ctx.t(read ? 'news.action.markUnread' : 'news.action.markRead'),
      onSelect: () => ctx.actions.toggleRead(article),
    })
    if (ctx.hasKnowledgeCapture) {
      actions.push({
        key: 'kb',
        icon: 'books.vertical',
        label: ctx.t('Save to Knowledge Base'),
        onSelect: () => ctx.actions.saveToKnowledgeBase(article),
      })
    }
    return actions
  }
}

// 时间线 / 收藏 / 事件详情共用的文章行（对应 NewsArticleRow.swift）。
// 状态槽互斥：正在朗读 → speaker.wave.2.fill；否则未读 → 6×6 品牌色圆点；已读 → 无标记。

import React from 'react'
import Icon from './Icon.jsx'
import { C, SPACE } from './theme.js'
import { relative } from '../lib/format.js'
import { imageURL } from '../lib/host.js'

const THUMB = 80

function Thumbnail({ url, isRead, blockedLabel }) {
  const [failed, setFailed] = React.useState(false)
  React.useEffect(() => { setFailed(false) }, [url])
  return (
    <div
      style={{
        position: 'relative',
        width: THUMB,
        height: THUMB,
        borderRadius: 11,
        overflow: 'hidden',
        background: 'color-mix(in srgb, var(--news-line) 55%, transparent)',
        opacity: isRead ? 0.72 : 1,
        flex: '0 0 auto',
      }}
    >
      <div style={{
        position: 'absolute', inset: 0, display: 'flex',
        alignItems: 'center', justifyContent: 'center', color: C.muted,
      }}
      >
        <Icon name="photo" size={20} title={failed ? blockedLabel : undefined} />
      </div>
      {failed ? null : (
        <img
          // 必须走 applet:// 字节通道 —— secure 模式的 CSP 直接挡死远端 https 图片。
          src={imageURL(url, THUMB)}
          alt=""
          loading="lazy"
          onError={() => setFailed(true)}
          style={{ position: 'absolute', inset: 0, width: '100%', height: '100%', objectFit: 'cover' }}
        />
      )}
    </div>
  )
}

export default function ArticleRow({
  article,
  isRead,
  relatedCount = 0,
  isSaved = false,
  isSpeaking = false,
  locale,
  t,
  now,
}) {
  const summary = article.summary || ''
  return (
    <div style={{ display: 'flex', alignItems: 'flex-start', gap: SPACE.s3, padding: '6px 0' }}>
      <div style={{ display: 'flex', flexDirection: 'column', gap: 5, minWidth: 0, flex: '1 1 auto' }}>
        <div style={{ display: 'flex', alignItems: 'baseline', gap: 7, minWidth: 0 }}>
          {isSpeaking ? (
            <Icon
              name="speaker.wave.2.fill"
              size={12}
              color={C.brand}
              style={{ position: 'relative', top: 1 }}
              title={t('news.broadcast.nowReading')}
            />
          ) : (!isRead ? (
            <span style={{
              width: 6, height: 6, borderRadius: 3, background: C.brand,
              flex: '0 0 auto', position: 'relative', top: -2,
            }}
            />
          ) : null)}
          <span
            className="news-clamp-3"
            style={{ fontSize: 16, fontWeight: 500, lineHeight: 1.32, color: isRead ? C.muted : C.ink, minWidth: 0 }}
          >
            {article.title}
          </span>
        </div>

        {summary ? (
          <span className="news-clamp-2" style={{ fontSize: 12, lineHeight: 1.38, color: C.muted }}>
            {summary}
          </span>
        ) : null}

        <div style={{ display: 'flex', alignItems: 'center', gap: 6, minWidth: 0, flexWrap: 'nowrap' }}>
          <span className="news-clamp-1" style={{ fontSize: 12, color: C.brand, minWidth: 0 }}>
            {article.sourceName}
          </span>
          <span style={{ fontSize: 12, color: C.muted, flex: '0 0 auto' }}>·</span>
          <span className="news-mono" style={{ fontSize: 12, color: C.muted, flex: '0 0 auto' }}>
            {relative(article.publishedAt, locale, now)}
          </span>
          {relatedCount > 0 ? (
            <span
              style={{ display: 'inline-flex', alignItems: 'center', gap: 3, fontSize: 12, color: C.muted, flex: '0 0 auto' }}
              aria-label={t('news.cluster.reportCount', relatedCount + 1)}
            >
              <Icon name="rectangle.stack" size={12} />
              {relatedCount + 1}
            </span>
          ) : null}
          {isSaved ? (
            <Icon name="bookmark.fill" size={11} color={C.brand} title={t('news.saved.favorites')} />
          ) : null}
        </div>
      </div>

      {article.imageURL ? (
        <Thumbnail url={article.imageURL} isRead={isRead} blockedLabel={t('news.x.imageBlocked')} />
      ) : null}
    </div>
  )
}

// 播报提示条 + 播报控制条（对应 NewsBroadcastBar.swift）。跨 Tab 常驻，贴在底栏之上。

import React from 'react'
import Icon from './Icon.jsx'
import { C, SPACE } from './theme.js'

export function BroadcastNotice({ messageKey, t, onDismiss }) {
  if (!messageKey) return null
  return (
    <button
      type="button"
      className="news-btn news-press"
      onClick={onDismiss}
      style={{
        display: 'flex', alignItems: 'center', gap: SPACE.s2, width: '100%',
        padding: `10px ${SPACE.s4}px`,
        background: C.blur,
        backdropFilter: 'saturate(180%) blur(20px)',
        WebkitBackdropFilter: 'saturate(180%) blur(20px)',
        borderTop: `0.5px solid ${C.line}`,
      }}
    >
      <Icon name="exclamationmark.triangle.fill" size={15} color={C.warning} />
      <span style={{ flex: '1 1 auto', fontSize: 13, color: C.ink, textAlign: 'left' }}>{t(messageKey)}</span>
      <Icon name="xmark" size={13} color={C.muted} />
    </button>
  )
}

function ControlButton({ icon, size, onClick, disabled, label }) {
  return (
    <button
      type="button"
      className="news-btn news-press"
      onClick={onClick}
      disabled={disabled}
      aria-label={label}
      style={{
        width: 36, height: 36, display: 'flex', alignItems: 'center', justifyContent: 'center',
        color: disabled ? C.muted : C.ink, opacity: disabled ? 0.4 : 1,
      }}
    >
      <Icon name={icon} size={size} />
    </button>
  )
}

export default function BroadcastBar({ broadcast, t, onOpenCurrent }) {
  if (!broadcast.active) return null
  const current = broadcast.current
  const total = broadcast.items.length
  const position = broadcast.index + 1

  return (
    <div style={{
      flex: '0 0 auto',
      background: C.blur,
      backdropFilter: 'saturate(180%) blur(20px)',
      WebkitBackdropFilter: 'saturate(180%) blur(20px)',
      borderTop: `0.5px solid ${C.line}`,
    }}
    >
      <div style={{ height: 2, background: 'color-mix(in srgb, var(--news-line) 60%, transparent)' }}>
        <div style={{
          height: 2, width: `${Math.round(broadcast.progress * 100)}%`, background: C.brand,
          transition: 'width 240ms linear',
        }}
        />
      </div>
      <div style={{ display: 'flex', alignItems: 'center', gap: SPACE.s2, padding: `6px ${SPACE.s3}px` }}>
        <button
          type="button"
          className="news-btn news-press"
          onClick={onOpenCurrent}
          aria-label={t('news.broadcast.openCurrent')}
          style={{ display: 'flex', alignItems: 'center', gap: 7, flex: '1 1 auto', minWidth: 0 }}
        >
          <Icon name="speaker.wave.2.fill" size={15} color={C.brand} />
          <span style={{ display: 'flex', flexDirection: 'column', gap: 1, minWidth: 0, textAlign: 'left' }}>
            <span className="news-clamp-1" style={{ fontSize: 14, fontWeight: 500, color: C.ink }}>
              {current ? current.title : t('news.broadcast.title')}
            </span>
            <span className="news-clamp-1 news-mono" style={{ fontSize: 12, color: C.muted }}>
              {`${position}/${total}${current && current.sourceName ? ` · ${current.sourceName}` : ''}`}
            </span>
          </span>
        </button>
        <ControlButton
          icon="backward.fill"
          size={15}
          disabled={broadcast.index === 0}
          onClick={() => broadcast.previous()}
          label={t('news.broadcast.previous')}
        />
        <ControlButton
          icon={broadcast.playing ? 'pause.fill' : 'play.fill'}
          size={18}
          onClick={() => (broadcast.playing ? broadcast.pause() : broadcast.resume())}
          label={t(broadcast.playing ? 'news.broadcast.pause' : 'news.broadcast.resume')}
        />
        <ControlButton
          icon="forward.fill"
          size={15}
          disabled={broadcast.index >= total - 1}
          onClick={() => broadcast.next()}
          label={t('news.broadcast.next')}
        />
        <ControlButton
          icon="xmark"
          size={15}
          onClick={() => broadcast.stop({ userInitiated: true })}
          label={t('news.broadcast.stop')}
        />
      </div>
    </div>
  )
}

// 事件簇详情（对应 NewsClusterDetailView）：首段事件标题 + 「N 篇报道」，
// 第二段列出簇内全部文章（发布时间倒序）；长按菜单只有「AI 分析」+「收藏 / 取消收藏」。

import React from 'react'
import ArticleList from './ArticleList.jsx'
import { SectionHeader } from './primitives.jsx'
import { C, SPACE } from './theme.js'

export default function ClusterDetail({ ctx, cluster }) {
  const articles = React.useMemo(
    () => [...cluster.articles].sort((a, b) => b.publishedAt - a.publishedAt),
    [cluster],
  )
  const items = React.useMemo(
    () => articles.map((article) => ({ id: article.id, lead: article, related: [] })),
    [articles],
  )

  const menuFor = React.useCallback((article) => {
    const actions = []
    if (ctx.hasAI) {
      actions.push({
        key: 'analyze',
        icon: 'sparkles',
        label: ctx.t('news.action.analyze'),
        onSelect: () => ctx.actions.analyze(article),
      })
    }
    const saved = ctx.savedKeys.has(article.id)
    actions.push({
      key: 'save',
      icon: saved ? 'bookmark.slash' : 'bookmark',
      label: ctx.t(saved ? 'news.action.unsave' : 'news.action.save'),
      onSelect: () => ctx.actions.toggleSaved(article),
    })
    return actions
  }, [ctx])

  return (
    <div className="news-scroll">
      <div style={{ padding: `${SPACE.s4}px ${SPACE.s4}px ${SPACE.s3}px`, display: 'flex', flexDirection: 'column', gap: 6 }}>
        <span style={{ fontSize: 18, fontWeight: 500, color: C.ink, lineHeight: 1.3 }}>{cluster.title}</span>
        <span style={{ fontSize: 13, color: C.muted }}>{ctx.t('news.cluster.reportCount', articles.length)}</span>
      </div>
      <SectionHeader>{ctx.t('news.cluster.sources')}</SectionHeader>
      <ArticleList items={items} ctx={ctx} menuFor={menuFor} />
      <div style={{ height: 24 }} />
    </div>
  )
}

// 资讯诊断（对应 NewsDiagnosticsView）：概览 → 最近一次刷新 → 逐源状态 → 立即刷新 / 清除缓存。

import React from 'react'
import Icon from './Icon.jsx'
import { Card, Row, SectionFooter, SectionHeader } from './primitives.jsx'
import { C, SPACE } from './theme.js'
import { bytes, duration, relative } from '../lib/format.js'

const STATUS_META = {
  success: { icon: 'checkmark.circle', color: C.brand, key: 'news.diagnostics.success' },
  empty: { icon: 'minus.circle', color: C.orange, key: 'news.diagnostics.empty' },
  failed: { icon: 'exclamationmark.circle', color: C.danger, key: 'news.diagnostics.failed' },
}

function failureText(state, t) {
  if (!state.failure) return null
  if (state.failure === 'http' && state.httpStatus) return `HTTP ${state.httpStatus}`
  return t(`news.diagnostics.failure.${state.failure}`)
}

export default function DiagnosticsPage({ ctx }) {
  const { agg, t, locale, now } = ctx
  const report = agg.lastReport
  const enabledCount = ctx.store.enabledFeeds.length

  return (
    <div className="news-scroll">
      <SectionHeader>{t('news.diagnostics.overview')}</SectionHeader>
      <Card>
        <Row
          title={t('news.diagnostics.lastUpdate')}
          detail={agg.lastUpdated ? relative(agg.lastUpdated, locale, now) : t('news.diagnostics.never')}
        />
        <Row title={t('news.diagnostics.timelineCount')} detail={agg.timeline.length} />
        <Row title={t('news.diagnostics.enabledSources')} detail={enabledCount} />
        <Row
          title={t('news.diagnostics.clustering')}
          detail={ctx.settings.clustering ? t('news.diagnostics.available') : t('news.diagnostics.disabled')}
        />
        <Row title={t('news.diagnostics.cache')} detail={bytes(ctx.store.contentCacheBytes())} last />
      </Card>

      <SectionHeader>{t('news.diagnostics.lastRun')}</SectionHeader>
      {report ? (
        <>
          <Card>
            <Row title={t('news.diagnostics.duration')} detail={duration((report.finishedAt - report.startedAt) / 1000, t)} />
            <Row title={t('news.diagnostics.fetchDuration')} detail={duration(report.fetchDuration, t)} />
            <Row title={t('news.diagnostics.processingDuration')} detail={duration(report.processingDuration, t)} />
            <Row
              title={t('news.diagnostics.enrichmentDuration')}
              detail={report.enrichmentDuration === null ? '—' : duration(report.enrichmentDuration, t)}
            />
            <Row title={t('news.diagnostics.fetched')} detail={report.fetchedArticleCount} />
            <Row title={t('news.diagnostics.duplicates')} detail={report.duplicateCount} />
            <Row title={t('news.diagnostics.clustered')} detail={report.clusteredArticleCount} />
            <Row
              title={t('news.diagnostics.successSources')}
              detail={report.sourceStates.filter((row) => row.status === 'success').length}
            />
            <Row
              title={t('news.diagnostics.emptySources')}
              detail={report.sourceStates.filter((row) => row.status === 'empty').length}
            />
            <Row
              title={t('news.diagnostics.failedSources')}
              detail={report.sourceStates.filter((row) => row.status === 'failed').length}
              last
            />
          </Card>
          <SectionFooter>{t('news.diagnostics.emptyFooter')}</SectionFooter>
        </>
      ) : (
        <Card><Row title={t('news.diagnostics.noSourceData')} last /></Card>
      )}

      <SectionHeader>{t('news.diagnostics.sources')}</SectionHeader>
      <Card>
        {report && report.sourceStates.length > 0 ? report.sourceStates.map((state, i) => {
          const meta = STATUS_META[state.status] || STATUS_META.failed
          const failure = failureText(state, t)
          return (
            <div
              key={`${state.id}-${state.sourceName}`}
              style={{
                display: 'flex', alignItems: 'center', gap: SPACE.s3,
                padding: `10px ${SPACE.s4}px`,
                borderBottom: i === report.sourceStates.length - 1 ? 'none' : `0.5px solid ${C.line}`,
              }}
            >
              <Icon name={meta.icon} size={16} color={meta.color} />
              <span style={{ display: 'flex', flexDirection: 'column', gap: 2, flex: '1 1 auto', minWidth: 0 }}>
                <span className="news-clamp-1" style={{ fontSize: 15, color: C.ink }}>{state.sourceName}</span>
                <span className="news-mono" style={{ fontSize: 12, color: C.muted }}>
                  {t('news.diagnostics.sourceDetail', state.itemCount, duration(state.duration, t))}
                </span>
                {failure ? <span style={{ fontSize: 12, color: C.danger }}>{failure}</span> : null}
              </span>
              <span style={{ fontSize: 13, color: meta.color, flex: '0 0 auto' }}>{t(meta.key)}</span>
            </div>
          )
        }) : (
          <Row title={t('news.diagnostics.noSourceData')} last />
        )}
      </Card>

      <div style={{ height: SPACE.s5 }} />
      <Card>
        <Row
          icon="arrow.clockwise"
          iconColor={C.brand}
          title={t('news.diagnostics.refreshNow')}
          onClick={() => ctx.actions.refresh(true)}
          accessory={null}
        />
        <Row
          icon="trash"
          iconColor={C.danger}
          title={t('news.subs.cache.clear')}
          danger
          onClick={() => ctx.actions.clearContentCache()}
          accessory={null}
          last
        />
      </Card>
      <div style={{ height: 32 }} />
    </div>
  )
}

// 资讯时间线：主题 chip 行（带折叠后计数）+ 左右横扫分页 + 刷新状态条 + 空态 + 长按操作。
// 传 sourceFeed 时复用为单订阅源下钻页（无 chips、无状态条、不回填播报队列）。

import React from 'react'
import Icon from './Icon.jsx'
import ArticleList, { buildArticleMenu } from './ArticleList.jsx'
import { EmptyState, PullRefresh, Spinner } from './primitives.jsx'
import Pager from './Pager.jsx'
import { C, SPACE } from './theme.js'
import { TOPIC_ORDER, topicKey } from '../lib/catalog.js'
import { buckets as computeBuckets, project } from '../lib/projection.js'
import { relative } from '../lib/format.js'

const TOPIC_OPTIONS = [null, ...TOPIC_ORDER]

function Chip({ label, count, selected, onClick, innerRef }) {
  return (
    <button
      ref={innerRef}
      type="button"
      className="news-btn news-press"
      onClick={onClick}
      style={{
        display: 'inline-flex', alignItems: 'center', gap: 5,
        padding: '7px 12px', borderRadius: 999, flex: '0 0 auto',
        fontSize: 13, fontWeight: selected ? 500 : 400,
        color: selected ? C.onBrand : C.ink,
        background: selected ? C.brand : 'color-mix(in srgb, var(--news-line) 50%, transparent)',
        transition: 'background 220ms ease, color 220ms ease',
      }}
    >
      <span>{label}</span>
      {count > 0 ? (
        <span className="news-mono" style={{ fontSize: 11, opacity: selected ? 0.82 : 1, color: selected ? C.onBrand : C.muted }}>
          {count}
        </span>
      ) : null}
    </button>
  )
}

function TopicChips({ options, selectedIndex, counts, onSelect, t }) {
  const scroller = React.useRef(null)
  const refs = React.useRef([])
  React.useEffect(() => {
    const node = refs.current[selectedIndex]
    const host = scroller.current
    if (!node || !host) return
    const target = node.offsetLeft - (host.clientWidth - node.clientWidth) / 2
    host.scrollTo({ left: Math.max(0, target), behavior: 'smooth' })
  }, [selectedIndex])

  return (
    <div
      ref={scroller}
      className="news-chips"
      style={{
        display: 'flex', gap: 8, overflowX: 'auto', overflowY: 'hidden',
        padding: `${SPACE.s2}px ${SPACE.s4}px`, background: C.bg, flex: '0 0 auto',
        scrollbarWidth: 'none',
      }}
    >
      {options.map((topic, index) => (
        <Chip
          key={topic || 'all'}
          innerRef={(node) => { refs.current[index] = node }}
          label={t(topicKey(topic))}
          count={counts[topic || 'all'] || 0}
          selected={index === selectedIndex}
          onClick={() => onSelect(index)}
        />
      ))}
    </div>
  )
}

/**
 * 刷新状态条。原生是四态（正在更新 / 尚未更新 / 部分来源需要检查 / 资讯已更新）；
 * 这里补上**第五态「被阻断」**：一条都没抓到且原因是权限 / 域名白名单 / 断网时，
 * 必须如实说出真因并给出修法，而不是含混地记成「尚未更新」——用户会以为是没有新闻。
 */
const BLOCKED_META = {
  permission: { titleKey: 'news.status.blocked.permission', hintKey: 'news.status.blocked.permission.hint', icon: 'lock.slash' },
  blocked: { titleKey: 'news.status.blocked.allowlist', hintKey: 'news.status.blocked.allowlist.hint', icon: 'exclamationmark.triangle' },
  offline: { titleKey: 'news.status.blocked.offline', hintKey: 'news.status.blocked.offline.hint', icon: 'wifi.slash' },
}

function RefreshStatusRow({ ctx, onOpenDiagnostics }) {
  const { agg, t, locale, now } = ctx
  const unsuccessful = agg.lastReport ? agg.unsuccessfulSourceCount : 0
  const blocked = agg.isRefreshing ? null : BLOCKED_META[agg.blockedReason]

  let titleKey = 'news.status.ready'
  if (agg.isRefreshing) titleKey = 'news.status.refreshing'
  else if (blocked) titleKey = blocked.titleKey
  else if (!agg.lastUpdated) titleKey = 'news.status.notUpdated'
  else if (unsuccessful > 0) titleKey = 'news.status.partial'

  let icon = 'checkmark.circle'
  if (blocked) icon = blocked.icon
  else if (!agg.lastUpdated) icon = 'clock.badge.questionmark'
  else if (unsuccessful > 0) icon = 'exclamationmark.triangle'
  const color = blocked ? C.danger : (unsuccessful > 0 ? C.orange : C.brand)

  return (
    <button
      type="button"
      className="news-btn news-press"
      onClick={onOpenDiagnostics}
      style={{
        display: 'flex', alignItems: 'center', gap: 10, width: '100%',
        padding: `10px ${SPACE.s4}px`,
        background: 'color-mix(in srgb, var(--news-line) 12%, transparent)',
      }}
    >
      <span style={{ width: 20, display: 'flex', justifyContent: 'center' }}>
        {agg.isRefreshing ? <Spinner size={16} color={C.muted} /> : <Icon name={icon} size={16} color={color} />}
      </span>
      <span style={{ display: 'flex', flexDirection: 'column', gap: 2, flex: '1 1 auto', minWidth: 0, textAlign: 'left' }}>
        <span style={{ fontSize: 12, color: blocked ? C.danger : C.ink }}>{t(titleKey)}</span>
        {blocked ? (
          <span style={{ fontSize: 12, color: C.muted, lineHeight: 1.35 }}>{t(blocked.hintKey)}</span>
        ) : (agg.lastUpdated ? (
          <span style={{ fontSize: 12, color: C.muted }}>
            {t('news.status.updated', relative(agg.lastUpdated, locale, now), agg.successfulSourceCount)}
          </span>
        ) : null)}
      </span>
      <Icon name="chevron.right" size={12} color={C.muted} style={{ opacity: 0.6 }} />
    </button>
  )
}

const BLOCKED_EMPTY = {
  permission: { icon: 'lock.slash', key: 'news.empty.blocked.permission' },
  blocked: { icon: 'exclamationmark.triangle', key: 'news.empty.blocked.allowlist' },
  offline: { icon: 'wifi.slash', key: 'news.empty.blocked.offline' },
}

function emptyDescriptor({ refreshing, query, topic, timelineEmpty, blockedReason }) {
  if (refreshing) return { icon: 'arrow.triangle.2.circlepath', key: 'news.empty.loading' }
  // 一条都没有 **且** 抓取整体被阻断时，空态必须说真因 —— 说「还没有新闻，下拉刷新」
  // 等于把「没权限」谎报成「没内容」，用户会一直下拉一个永远不会成功的刷新。
  if (timelineEmpty && BLOCKED_EMPTY[blockedReason]) return BLOCKED_EMPTY[blockedReason]
  if (String(query || '').trim()) return { icon: 'magnifyingglass', key: 'news.empty.search' }
  if (topic && !timelineEmpty) return { icon: 'tray', key: 'news.empty.topic' }
  return { icon: 'newspaper', key: 'news.empty.feed' }
}

function TopicPage({ items, ctx, topic, isSource, loadingSource, onRefresh, refreshing, showStatus, onOpenDiagnostics }) {
  const scrollRef = React.useRef(null)
  const menuFor = React.useMemo(
    () => buildArticleMenu(ctx, { includeCluster: !isSource }),
    [ctx, isSource],
  )
  const descriptor = emptyDescriptor({
    refreshing: isSource ? loadingSource : ctx.agg.isRefreshing,
    query: ctx.query,
    topic,
    timelineEmpty: ctx.agg.timeline.length === 0,
    // 单源下钻页有自己的抓取链路，不套用整条时间线的阻断判定。
    blockedReason: isSource ? null : ctx.agg.blockedReason,
  })

  return (
    <PullRefresh onRefresh={onRefresh} refreshing={refreshing} scrollRef={scrollRef}>
      {showStatus ? <RefreshStatusRow ctx={ctx} onOpenDiagnostics={onOpenDiagnostics} /> : null}
      {items.length === 0 ? (
        <EmptyState icon={descriptor.icon} text={ctx.t(descriptor.key)} />
      ) : (
        <ArticleList items={items} ctx={ctx} menuFor={menuFor} />
      )}
      <div style={{ height: 24 }} />
    </PullRefresh>
  )
}

export default function FeedPage({ ctx, sourceFeed }) {
  const isSource = !!sourceFeed
  const [topicIndex, setTopicIndex] = React.useState(0)
  const [sourceArticles, setSourceArticles] = React.useState([])
  const [loadingSource, setLoadingSource] = React.useState(false)
  const pagerRef = React.useRef(null)

  const options = { query: ctx.query, hideRead: ctx.settings.hideRead, readKeys: ctx.readKeys, collapseClusters: ctx.settings.collapseClusters }

  const buckets = React.useMemo(() => {
    if (isSource) return null
    return computeBuckets(ctx.agg.timeline, options)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [ctx.agg.timeline, ctx.agg.timelineRevision, ctx.query, ctx.settings.hideRead, ctx.settings.collapseClusters, ctx.readVersion, isSource])

  const sourceItems = React.useMemo(() => {
    if (!isSource) return []
    return project(sourceArticles, { ...options, topic: null })
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [sourceArticles, ctx.query, ctx.settings.hideRead, ctx.settings.collapseClusters, ctx.readVersion, isSource])

  const counts = React.useMemo(() => {
    if (!buckets) return {}
    const out = {}
    for (const key of Object.keys(buckets)) out[key] = buckets[key].length
    return out
  }, [buckets])

  const selectedTopic = TOPIC_OPTIONS[topicIndex]

  // 回填「用户此刻看到的那串文章」——顶栏播报按钮据此建队列。只取 lead，只有资讯 Tab 回填。
  React.useEffect(() => {
    if (isSource || !buckets) return
    ctx.actions.setVisibleArticles((buckets[selectedTopic || 'all'] || []).map((entry) => entry.lead))
  }, [buckets, selectedTopic, isSource]) // eslint-disable-line react-hooks/exhaustive-deps

  const loadSource = React.useCallback(async () => {
    if (!isSource) return
    setLoadingSource(true)
    const result = await ctx.actions.fetchSource(sourceFeed)
    setSourceArticles(result)
    setLoadingSource(false)
  }, [isSource, sourceFeed]) // eslint-disable-line react-hooks/exhaustive-deps

  React.useEffect(() => { loadSource() }, [loadSource])

  if (isSource) {
    return (
      <TopicPage
        items={sourceItems}
        ctx={ctx}
        topic={null}
        isSource
        loadingSource={loadingSource}
        refreshing={loadingSource}
        onRefresh={loadSource}
        showStatus={false}
      />
    )
  }

  return (
    <>
      <TopicChips
        options={TOPIC_OPTIONS}
        selectedIndex={topicIndex}
        counts={counts}
        onSelect={(index) => { if (pagerRef.current) pagerRef.current.slideTo(index); else setTopicIndex(index) }}
        t={ctx.t}
      />
      <Pager
        ref={pagerRef}
        count={TOPIC_OPTIONS.length}
        index={topicIndex}
        onIndex={setTopicIndex}
        renderPage={(index) => {
          const topic = TOPIC_OPTIONS[index]
          return (
            <TopicPage
              items={(buckets && buckets[topic || 'all']) || []}
              ctx={ctx}
              topic={topic}
              isSource={false}
              loadingSource={false}
              refreshing={ctx.agg.isRefreshing}
              onRefresh={() => ctx.actions.refresh(true)}
              showStatus={ctx.settings.showRefreshStatus}
              onOpenDiagnostics={() => ctx.actions.navigate({ name: 'diagnostics' })}
            />
          )
        }}
      />
    </>
  )
}

// 选项行（对应 SwiftUI 的 Picker）：点开底部面板选一个。设置页与添加订阅源表单共用。

import React from 'react'
import Icon from './Icon.jsx'
import { Row, Sheet } from './primitives.jsx'
import { C, SPACE } from './theme.js'

export default function PickerRow({ icon, title, value, options, onChange, disabled, last, cancelLabel }) {
  const [open, setOpen] = React.useState(false)
  const selected = options.find((option) => option.value === value)
  return (
    <>
      <Row
        icon={icon}
        title={title}
        detail={selected ? selected.label : ''}
        accessory={<Icon name="chevron.down" size={12} color={disabled ? C.line : C.muted} />}
        onClick={disabled ? undefined : () => setOpen(true)}
        last={last}
      />
      <Sheet visible={open} onClose={() => setOpen(false)}>
        <div style={{ padding: `${SPACE.s4}px ${SPACE.s4}px ${SPACE.s2}px`, fontSize: 13, color: C.muted }}>{title}</div>
        {options.map((option, i) => (
          <button
            key={String(option.value)}
            type="button"
            className="news-btn news-press"
            onClick={() => { setOpen(false); onChange(option.value) }}
            style={{
              display: 'flex', alignItems: 'center', gap: SPACE.s3, width: '100%',
              padding: `13px ${SPACE.s4}px`, fontSize: 16, color: C.ink,
              borderTop: `0.5px solid ${C.line}`,
              borderBottom: i === options.length - 1 ? `0.5px solid ${C.line}` : 'none',
            }}
          >
            <span style={{ flex: '1 1 auto' }}>{option.label}</span>
            {option.value === value ? <Icon name="checkmark" size={16} color={C.brand} /> : null}
          </button>
        ))}
        {cancelLabel ? (
          <button
            type="button"
            className="news-btn news-press"
            onClick={() => setOpen(false)}
            style={{ display: 'block', width: '100%', padding: `14px ${SPACE.s4}px`, color: C.brand, fontSize: 16, textAlign: 'center' }}
          >
            {cancelLabel}
          </button>
        ) : null}
      </Sheet>
    </>
  )
}

// 左右横扫分页（对应原生 `TabView(.page)`）：资讯页的主题分页与收藏页的两个子 Tab 共用。
// 只挂载「上一页 / 当前页 / 下一页」三屏，切页动画 easeInOut 0.22s，与 chip / 分段控件双向联动。

import React from 'react'

const DURATION = 220
const LOCK_SLOP = 6

const Pager = React.forwardRef(function Pager({ count, index, onIndex, renderPage, style }, ref) {
  const hostRef = React.useRef(null)
  const [drag, setDrag] = React.useState(0)
  const [animating, setAnimating] = React.useState(false)
  const gesture = React.useRef({ active: false, startX: 0, startY: 0, lock: null, width: 1 })
  const commitRef = React.useRef(null)

  const settle = React.useCallback((nextIndex, direction) => {
    const width = hostRef.current ? hostRef.current.clientWidth : 1
    if (nextIndex === index) {
      setAnimating(true)
      setDrag(0)
      window.setTimeout(() => setAnimating(false), DURATION)
      return
    }
    commitRef.current = nextIndex
    setAnimating(true)
    setDrag(-direction * width)
    window.setTimeout(() => {
      setAnimating(false)
      setDrag(0)
      const target = commitRef.current
      commitRef.current = null
      if (target !== null) onIndex(target)
    }, DURATION)
  }, [index, onIndex])

  React.useImperativeHandle(ref, () => ({
    slideTo(nextIndex) {
      if (nextIndex === index || nextIndex < 0 || nextIndex >= count) return
      settle(nextIndex, nextIndex > index ? 1 : -1)
    },
  }), [count, index, settle])

  const onTouchStart = (event) => {
    if (animating || event.touches.length !== 1) return
    const touch = event.touches[0]
    gesture.current = {
      active: true,
      startX: touch.clientX,
      startY: touch.clientY,
      lock: null,
      width: hostRef.current ? hostRef.current.clientWidth : 1,
    }
  }

  const onTouchMove = (event) => {
    const state = gesture.current
    if (!state.active) return
    const touch = event.touches[0]
    const dx = touch.clientX - state.startX
    const dy = touch.clientY - state.startY
    if (state.lock === null) {
      if (Math.abs(dx) < LOCK_SLOP && Math.abs(dy) < LOCK_SLOP) return
      state.lock = Math.abs(dx) > Math.abs(dy) ? 'h' : 'v'
    }
    if (state.lock !== 'h') return
    if (event.cancelable) event.preventDefault()
    // 首/末页做橡皮筋阻尼，避免滑出空白屏。
    const atStart = index === 0 && dx > 0
    const atEnd = index === count - 1 && dx < 0
    setDrag(atStart || atEnd ? dx * 0.28 : dx)
  }

  const onTouchEnd = () => {
    const state = gesture.current
    if (!state.active) return
    state.active = false
    if (state.lock !== 'h') return
    const threshold = Math.max(48, state.width * 0.22)
    let next = index
    if (drag <= -threshold && index < count - 1) next = index + 1
    else if (drag >= threshold && index > 0) next = index - 1
    settle(next, next > index ? 1 : (next < index ? -1 : 0))
  }

  // translate 的百分比按**自身**尺寸算 —— 轨道是宿主的 300%，故一屏 = 100%/3，
  // 与 `.news-pager-slot` 的 `calc(100% / 3)` 精确同宽（写死 33.3333% 会差出亚像素并累积）。
  const offset = `calc(-100% / 3 + ${drag}px)`
  return (
    <div
      ref={hostRef}
      style={{ overflow: 'hidden', flex: '1 1 auto', minHeight: 0, display: 'flex', ...style }}
      onTouchStart={onTouchStart}
      onTouchMove={onTouchMove}
      onTouchEnd={onTouchEnd}
      onTouchCancel={onTouchEnd}
    >
      <div
        className="news-pager-track"
        style={{
          transform: `translate3d(${offset}, 0, 0)`,
          transition: animating ? `transform ${DURATION}ms cubic-bezier(0.42, 0, 0.58, 1)` : 'none',
        }}
      >
        <div className="news-pager-slot">{index - 1 >= 0 ? renderPage(index - 1) : null}</div>
        <div className="news-pager-slot">{renderPage(index)}</div>
        <div className="news-pager-slot">{index + 1 < count ? renderPage(index + 1) : null}</div>
      </div>
    </div>
  )
})

